import type { FilterValue } from 'models/Filters';
import {
  type DerivedTimePeriodSelection,
  resolveTimePeriodSelection,
} from 'utils/timePeriod/timePeriodAvailability';

import { getCanonicalVolumeTimePeriodType } from './getCanonicalVolumeTimePeriodType';

interface GetPerformanceToolVolumeTimePeriodDisplaySelectionParams {
  volumeChartPeriodType: string | null | undefined;
  dtEnd: FilterValue | undefined;
  cutoffDate: string | null | undefined;
}

export const getPerformanceToolVolumeTimePeriodDisplaySelection = ({
  volumeChartPeriodType,
  dtEnd,
  cutoffDate,
}: GetPerformanceToolVolumeTimePeriodDisplaySelectionParams): DerivedTimePeriodSelection | null => {
  if (!volumeChartPeriodType) return null;

  const periodType = getCanonicalVolumeTimePeriodType(volumeChartPeriodType);
  if (!periodType) return null;

  return resolveTimePeriodSelection(periodType, dtEnd, cutoffDate);
};
